import pandas as pd

def clean(df):
    df = df.copy()
    # exact duplicate rows
    df = df.drop_duplicates()
    # strip label variants / extra spaces
    for col in ["island", "species", "penguin_id", "sex"]:
        if col in df.columns:
            df[col] = df[col].astype("string").str.strip()
    # parse numbers written as text / with commas
    num_cols = ["bill_length_mm", "bill_depth_mm", "flipper_length_mm", "body_mass_g", "year"]
    for col in num_cols:
        if col in df.columns:
            df[col] = df[col].astype(str).str.replace(",", "", regex=False)
            df[col] = pd.to_numeric(df[col], errors="coerce")
    # range filter for body mass
    if "body_mass_g" in df.columns:
        df = df[(df["body_mass_g"] >= 2500) & (df["body_mass_g"] <= 6500)]
    return df

def answer(df):
    dfc = clean(df)
    out = dfc.groupby("sex")["body_mass_g"].mean()
    return {str(k): float(v) for k, v in out.items()}
